import { personalNoteRows, PERSONAL_NOTE_LIMIT } from './personal-notes.js';
import { journalPage, renderJournalPager } from './journal-pagination.js';
export function renderPersonalNotes(s, ui, { query = '', page = 0, archived = false, scope = archived ? 'archived' : 'current', draft = { text: '', saving: false, error: '' } } = {}) {
  const { e, button, paragraphs, date } = ui, all = personalNoteRows(s), own = all.filter(n => n.own), activeCount = own.filter(n => !n.archived).length, archivedCount = own.length - activeCount, familyCount = all.length - own.length;
  const scoped = all.filter(n => scope === 'family' ? !n.own : n.own && n.archived === (scope === 'archived')), matched = scoped.filter(n => !query || [n.text, n.ownerName, n.generation ? 'Generation ' + n.generation : ''].join(' ').toLowerCase().includes(query.toLowerCase())), view = journalPage(matched.slice().reverse(), page, 20);
  return `<section class="personal-notes" aria-labelledby="personal-notes-heading"><h2 id="personal-notes-heading" tabindex="-1">Personal Notes</h2><p>Only your own reminders can be changed. Earned events and discoveries stay as recorded. Archived notes can be restored; nothing is deleted.</p><div class="quick-actions">${button(`Current personal notes (${activeCount})`, 'personal-notes-scope', 'current', 'secondary small', false, scope === 'current')}${button(`Archived personal notes (${archivedCount})`, 'personal-notes-scope', 'archived', 'secondary small', false, scope === 'archived')}${button(`Family records (${familyCount})`, 'personal-notes-scope', 'family', 'secondary small', false, scope === 'family')}</div>${renderJournalPager(view, 'personal', scope === 'family' ? 'Family personal-note records' : scope === 'archived' ? 'Archived personal notes' : 'Current personal notes', ui, { total: scoped.length, query })}${view.rows.map(n => `<article class="remembered-entry personal-note" data-personal-note="${e(n.key)}"><small>${e(date(n.day))} · ${e(n.ownerName)}${n.generation ? ` · Generation ${n.generation}` : ' · Ownership not recorded'}</small><h3>${n.own ? 'Your Note' : 'Family Note'}${n.archived ? ' · Archived' : ''}</h3><div class="personal-note-text" data-verbatim><p>${e(n.text)}</p></div>${n.own ? `<div class="quick-actions">${!n.archived ? button('Edit note', 'personal-note-edit', n.key, 'secondary small') : ''}${button(n.archived ? 'Restore note' : 'Archive note', 'personal-note-archive', n.key, 'ghost small')}</div>` : '<p class="small-copy">Read-only family record. An heir cannot change an earlier life’s note. Unattributed legacy notes stay read-only when their generation is uncertain.</p>'}</article>`).join('') || `<p>${query ? 'No personal notes match this search in this view.' : scope === 'family' ? 'No earlier family notes have been recorded.' : scope === 'archived' ? 'No personal notes are archived.' : 'No current personal notes have been kept.'}</p>`}<p class="small-copy">${own.length} / ${PERSONAL_NOTE_LIMIT} notes kept by this life, including its archive. Earlier lives and unattributed legacy notes are kept separately under Family records.</p>${scope === 'current' ? `<form id="player-note" aria-busy="${Boolean(draft.saving)}"><label for="note-text">Write a Note</label><p id="note-draft-help" class="small-copy">Your draft stays with this life while this page is open. Keep Note to save it before reloading or closing the page.</p><textarea id="note-text" name="note" maxlength="2000" rows="4" required aria-describedby="note-draft-help note-draft-status" placeholder="A name, a destination, something to remember…"${(own.length >= PERSONAL_NOTE_LIMIT && !draft.receipt) || draft.saving ? ' disabled' : ''}>${e(draft.text)}</textarea><p id="note-draft-status" class="small-copy" role="status">${e(draft.error || (draft.saving ? 'Saving your note…' : draft.text ? 'Unsubmitted draft. Navigation does not save it.' : ''))}</p><div class="personal-note-actions"><button type="submit" class="button secondary" ${(own.length >= PERSONAL_NOTE_LIMIT && !draft.receipt) || draft.saving ? 'disabled' : ''}>${draft.saving ? 'Saving Note…' : draft.receipt ? 'Retry Saving Note' : 'Keep Note'}</button>${button('Discard Draft', 'personal-note-discard', '', 'ghost', draft.saving || !draft.text)}${button('Return to Discoveries', 'personal-note-back', '', 'ghost')}</div></form>` : ''}</section>`;
}
export function renderPersonalNoteReview(pending, ui) {
  if (!pending) return '';
  const { e, button, paragraphs, date } = ui, n = pending.note, editing = pending.mode === 'edit';
  const body = editing ? `<h2 id="personal-note-review-title">Edit your note</h2><p>${e(date(n.day))}. The original date stays unchanged. Only this personal note will change.</p><form id="personal-note-edit-form"><label for="personal-note-text">Your note</label><textarea id="personal-note-text" name="note" maxlength="2000" rows="7" required>${e(n.text)}</textarea><div class="modal-buttons"><button type="submit" class="button primary">Save note</button>${button('Cancel', 'close-modal', '', 'ghost')}</div></form>` : `<h2 id="personal-note-review-title">${n.archived ? 'Restore' : 'Archive'} your note?</h2><p>${n.archived ? 'This puts the note back with your current personal notes.' : 'This moves the note to Archived personal notes. You can restore it there at any time; its text and date are kept.'}</p><div class="personal-note-text" data-verbatim><small>${e(date(n.day))}</small><p>${e(n.text)}</p></div><div class="modal-buttons">${button(n.archived ? 'Restore note' : 'Archive note', 'personal-note-confirm', '', 'primary')}${button('Cancel', 'close-modal', '', 'ghost')}</div>`;
  return `<div class="modal-overlay"><section class="modal personal-note-dialog" role="dialog" aria-modal="true" aria-labelledby="personal-note-review-title"><button class="modal-close button ghost" type="button" data-op="close-modal" aria-label="Cancel note changes">×</button>${body}</section></div>`;
}
